const listInvites = `-- name: ListInvites :many
SELECT org_id, id, email, role, app, token_hash, expires_at, accepted_at, accepted_user_id, accepted_membership_id, revoked_at, invited_by_membership_id, created_by, created_at, last_modified_by, last_modified_at FROM invites
WHERE org_id = $1
  AND ($2::uuid IS NULL OR invited_by_membership_id = $2::uuid)
  AND ($3::text IS NULL
       OR ($3::text = 'pending' AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now())
       OR ($3::text = 'accepted' AND accepted_at IS NOT NULL)
       OR ($3::text = 'revoked' AND revoked_at IS NOT NULL)
       OR ($3::text = 'expired' AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at <= now()))
  AND ($4::timestamptz IS NULL OR (created_at, id) < ($4::timestamptz, $5::uuid))
ORDER BY created_at DESC, id DESC
LIMIT $6
`

type ListInvitesParams struct {
	OrgID     uuid.UUID
	InvitedBy pgtype.UUID
	Status    pgtype.Text
	BeforeAt  pgtype.Timestamptz
	BeforeID  pgtype.UUID
	PageLimit int32
}

// Newest first, by status, optionally only one member's, from a cursor.
func (q *Queries) ListInvites(ctx context.Context, arg ListInvitesParams) ([]Invite, error) {
	rows, err := q.db.Query(ctx, listInvites,
		arg.OrgID,
		arg.InvitedBy,
		arg.Status,
		arg.BeforeAt,
		arg.BeforeID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Invite{}
	for rows.Next() {
		var i Invite
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.Email,
			&i.Role,
			&i.App,
			&i.TokenHash,
			&i.ExpiresAt,
			&i.AcceptedAt,
			&i.AcceptedUserID,
			&i.AcceptedMembershipID,
			&i.RevokedAt,
			&i.InvitedByMembershipID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.LastModifiedBy,
			&i.LastModifiedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

