const revokeSessionsOfOrg = `-- name: RevokeSessionsOfOrg :many
UPDATE sessions SET revoked_at = now(), revoked_reason = $1
WHERE active_org_id = $2 AND revoked_at IS NULL AND expires_at > now()
RETURNING id, user_id, active_org_id, active_membership_id, refresh_token_hash, signed_in_org_id, expires_at, last_seen_at, revoked_at, idle_timeout_seconds, user_agent, revoked_reason, created_by, created_at, last_modified_by, last_modified_at, impersonation_id
`

type RevokeSessionsOfOrgParams struct {
	Reason pgtype.Text
	OrgID  pgtype.UUID
}

// Every live session working in an org, ended with a reason: the org is
// closing. Rows are returned so each is audited and pushed.
func (q *Queries) RevokeSessionsOfOrg(ctx context.Context, arg RevokeSessionsOfOrgParams) ([]Session, error) {
	rows, err := q.db.Query(ctx, revokeSessionsOfOrg, arg.Reason, arg.OrgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Session{}
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.ActiveOrgID,
			&i.ActiveMembershipID,
			&i.RefreshTokenHash,
			&i.SignedInOrgID,
			&i.ExpiresAt,
			&i.LastSeenAt,
			&i.RevokedAt,
			&i.IdleTimeoutSeconds,
			&i.UserAgent,
			&i.RevokedReason,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.LastModifiedBy,
			&i.LastModifiedAt,
			&i.ImpersonationID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

