const upsertTotp = `-- name: UpsertTotp :one
INSERT INTO mfa_totp (user_id, wrapped_secret, kms_key_version)
VALUES ($1, $2, $3)
ON CONFLICT (user_id) DO UPDATE SET wrapped_secret = excluded.wrapped_secret, kms_key_version = excluded.kms_key_version, confirmed_at = NULL, last_used_step = 0
WHERE mfa_totp.confirmed_at IS NULL
RETURNING user_id, wrapped_secret, kms_key_version, confirmed_at, last_used_step, created_by, created_at, last_modified_by, last_modified_at
`

type UpsertTotpParams struct {
	UserID        uuid.UUID
	WrappedSecret []byte
	KmsKeyVersion string
}

// global: an authenticator is a person's. Enrolling again before confirming
// replaces the unconfirmed secret; a confirmed one is replaced only after
// a reset.
func (q *Queries) UpsertTotp(ctx context.Context, arg UpsertTotpParams) (MfaTotp, error) {
	row := q.db.QueryRow(ctx, upsertTotp, arg.UserID, arg.WrappedSecret, arg.KmsKeyVersion)
	var i MfaTotp
	err := row.Scan(
		&i.UserID,
		&i.WrappedSecret,
		&i.KmsKeyVersion,
		&i.ConfirmedAt,
		&i.LastUsedStep,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastModifiedBy,
		&i.LastModifiedAt,
	)
	return i, err
}

